SELECT n.n_name, SUM(l.l_extendedprice*(1-l.l_discount)) AS revenue FROM tpch_customer c JOIN tpch_orders o ON c.c_custkey=o.o_custkey JOIN tpch_lineitem l ON l.l_orderkey=o.o_orderkey JOIN tpch_supplier s ON s.s_suppkey=l.l_suppkey AND s.s_nationkey=c.c_nationkey JOIN tpch_nation n ON n.n_nationkey=s.s_nationkey JOIN tpch_region r ON r.r_regionkey=n.n_regionkey WHERE r.r_name='ASIA' AND o.o_orderdate >= '1994-01-01' AND o.o_orderdate < '1995-01-01' GROUP BY n.n_name ORDER BY revenue DESC, n.n_name;
